const handle = api.chat.registerContentProcessor((ctx) => {
  const m = ctx.content.match(/<state>([sS]*?)</state>/);
  if (!m) return;
  return {
    content: ctx.content.replace(m[0], '').trim(),
    extra: { tracker: { state: m[1] } },
  };
}, { origin: 'create' });

